INSERT INTO cuotiben_card (id, user_id, src, subject, tag, kind, question, my_answer, answer, principle, note, mastered, created_at) VALUES
('err-20261018-01', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P35', '数学', '一元二次方程定义/概念辨析', 'choice', '下列方程，属于一元二次方程的是( )。A. 1/(x²-4)=2  B. 2x+y=3  C. 2x(x-1)=2x²+4  D. 2x(x+5)-x²=0', 'C', 'D', '一元二次方程定义：只含一个未知数、未知数最高次数为2的整式方程。', 'C 化简后 2x² 相消变成 -2x=4，是一元一次；D 化简得 x²+10x=0 才是一元二次。化简后再判断。', 0, 1760790000000),
('err-20261018-02', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P35', '数学', '配方法/概念理解', 'choice', '一元二次方程 x²+px+q=0 用配方法配成 (x+m)²=n 时，正确的是( )。A. m是p的一半  B. m是p的一半的平方  C. m是p的2倍  D. m是p的一半的相反数', 'B', 'A', '配方法：x²+px+(p/2)²=(x+p/2)²，所以 m=p/2。', '混淆了 m 和 n：m=p/2，n=(p/2)²-q。B 选项说的是 n 的形式。', 0, 1760790000000),
('err-20261018-03', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P35', '数学', '直接开平方法/成立条件', 'choice', '如果关于x的方程 (x-9)²=m+4 可以用直接开平方法求解，那么 m 的取值范围是( )。A. m>3  B. m≥3  C. m>-4  D. m≥-4', 'B', 'D', '直接开平方法要求等号右边非负。', '条件是 m+4≥0 即 m≥-4。误把 9 当条件，9 在左边平方里与 m 无关。', 0, 1760790000000),
('err-20261018-05', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P35', '数学', '配方法/计算失误', 'solve', '解方程：x²+4x-12=0（配方法）', 'x²+4x+4=12+2 → (x+2)²=14 → x=-2±√14', '(x+2)²=16 → x+2=±4 → x₁=2，x₂=-6', '配方法：移项→两边加一次项系数一半的平方→开平方。', '12+4=16 不是 14。基础加法算错，配方法最后一步开平方前先检查数字。', 0, 1760790000000),
('err-20261018-06', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P36', '数学', '因式分解法/方法错误', 'solve', '解方程：(x+3)(x-1)=5（因式分解法）', '(x+3)(x-1)-5=0 → x₁=-8，x₂=-4', '展开：x²+2x-8=0 → (x+4)(x-2)=0 → x₁=-4，x₂=2', '因式分解法必须先化为 ax²+bx+c=0 标准形式。', '不能把 5 直接拆进两个因式。右边不是 0 时必须先展开整理。', 0, 1760790000000),
('err-20261018-072', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P36', '数学', '公式法/移项变号', 'solve', '解方程：2x²+4=7x', 'a=2，b=4，c=-7（符号错）', '2x²-7x+4=0，a=2，b=-7，c=4，x=(7±√17)/4', '公式法先化标准形式，移项要变号。', '7x 移到左边是 -7x。b=-7 不是 b=4，c=4 不是 c=-7。', 0, 1760790000000),
('err-20261018-073', '2aa317f2-bc12-4788-be2f-e2448b6cf7d9', '创新思维·八年级 P36', '数学', '直接开平方法/漏解', 'solve', '解方程：x²-6x+9=(5-2x)²', 'x₁=0，x₂=6', '(x-3)²=(5-2x)² → x-3=±(5-2x) → x₁=8/3，x₂=2', 'A²=B² → A=±B，两种情况都要解。', '开平方后只算了一种情况。x-3=5-2x 得 8/3；x-3=-(5-2x) 得 2。', 0, 1760790000000);
